def key_shape(grid):
    """The 8-connected component of the rarest non-zero color, as (dr,dc) offsets from its top-left cell."""
    from collections import deque
    vals={v for row in grid for v in row if v!=0}
    key=min(vals, key=lambda v: sum(row.count(v) for row in grid))
    cells={(i,j) for i,row in enumerate(grid) for j,v in enumerate(row) if v==key}
    start=min(cells); seen={start}; q=deque([start]); comp=[start]
    while q:
        r,c=q.popleft()
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                n=(r+dr,c+dc)
                if n in cells and n not in seen:
                    seen.add(n); q.append(n); comp.append(n)
    r0=min(r for r,c in comp); c0=min(c for r,c in comp)
    return sorted((r-r0,c-c0) for r,c in comp), key

def stamp_all(grid):
    """Stamp a copy of the key shape at every position where all its cells land on 0 cells of the input."""
    shape,key=key_shape(grid); H,W=len(grid),len(grid[0])
    h=max(dr for dr,dc in shape)+1; w=max(dc for dr,dc in shape)+1
    res=[row[:] for row in grid]
    for r in range(H-h+1):
        for c in range(W-w+1):
            if all(grid[r+dr][c+dc]==0 for dr,dc in shape):
                for dr,dc in shape: res[r+dr][c+dc]=key
    return res

