def l_strokes(grid, bg):
    """All L-shaped strokes (two perpendicular runs sharing a corner cell): a list of (color, cells as a set)."""
    h, w = len(grid), len(grid[0])
    out = []
    for c in sorted({v for row in grid for v in row} - {bg}):
        cells = {(i, j) for i in range(h) for j in range(w) if grid[i][j] == c}
        if len(cells) < 3:
            continue
        for cy, cx in cells:
            vert = {(y, cx) for y, x in cells}
            hor = {(cy, x) for y, x in cells}
            if (vert | hor) == cells and len(vert) >= 2 and len(hor) >= 2:
                out.append((c, cells))
